<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<button
					type="button"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-primary transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					:aria-label="`Kembali ke ${backLabel}`"
					@click="goBack"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</button>
				<div class="flex min-w-0 flex-1 items-center gap-1.5">
					<span class="truncate font-medium text-ui-ink-gray-900">{{ name }}</span>
					<span
						v-if="d"
						class="shrink-0 rounded-full px-2 py-0.5 text-xs font-medium"
						:class="statusBadge(d.status)"
						>{{ d.status || '—' }}</span
					>
				</div>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="app-container-narrow flex-1 px-4 py-4 md:px-6">
			<pre v-if="error" class="whitespace-pre-wrap py-4 text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<p v-else-if="loading" class="py-6 text-sm text-ui-ink-gray-500">Memuat…</p>

			<template v-else-if="d">
				<!-- ===== Perubahannya ===== -->
				<div
					class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-5 shadow-sm"
				>
					<p class="text-xs font-semibold uppercase tracking-wide text-ui-ink-gray-400">
						Perubahan Periode
					</p>

					<div class="mt-3 space-y-2.5">
						<div class="rounded-xl bg-ui-surface-gray-50 px-3 py-2.5">
							<p class="text-xs text-ui-ink-gray-400">Semula</p>
							<p class="mt-0.5 text-sm text-ui-ink-gray-500 line-through">
								{{
									rentang(
										d.from_date_semula,
										d.to_date_semula,
										!d.to_date_semula
									)
								}}
							</p>
							<p class="mt-0.5 text-xs text-ui-ink-gray-400">
								{{ angka(d.total_hari_semula) }} hari
							</p>
						</div>

						<div
							class="rounded-xl border border-primary/20 bg-ui-surface-blue-50 px-3 py-2.5"
						>
							<p class="text-xs text-primary/70">Menjadi</p>
							<p class="mt-0.5 text-sm font-semibold text-ui-ink-gray-900">
								{{ rentangBaru }}
							</p>
						</div>

						<!-- Hari kerja sesudah batas sakit pada rentang baru — diputuskan
						     Ketua; pembagian angka masih menunggu jawaban karyawan. -->
						<div
							v-if="d.hari_di_atas_batas"
							class="rounded-xl border border-ui-line-violet-200 bg-ui-surface-violet-50 px-3 py-2.5 text-sm text-ui-ink-violet-800"
						>
							<p class="font-semibold">
								Kelebihan {{ angka(d.hari_di_atas_batas) }} hari kerja dari batas
								{{ d.batas_hari_sakit }} hari kerja.
							</p>
							<p v-if="sudahDibagi" class="mt-1 space-x-1">
								<template v-for="(b, i) in rincian" :key="b.label">
									<span v-if="i">·</span>
									<span><b>{{ angka(b.hari) }} hari</b> {{ b.label }}</span>
								</template>
							</p>
							<p
								v-if="d.status === 'Menunggu Persetujuan Karyawan'"
								class="mt-1 text-xs font-medium"
							>
								Menunggu jawaban {{ d.milik_saya ? 'Anda' : 'karyawan' }}.
							</p>
							<p v-if="d.keputusan_karyawan" class="mt-1 text-xs font-medium">
								{{
									d.keputusan_karyawan === 'Setuju'
										? 'Diterima karyawan.'
										: 'Ditolak karyawan. Penyesuaian batal.'
								}}
							</p>
						</div>
					</div>
				</div>

				<!-- ===== Rincian ===== -->
				<div
					class="mt-4 rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-5 shadow-sm"
				>
					<dl class="space-y-3 text-sm">
						<div class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Karyawan</dt>
							<dd class="min-w-0 flex-1 text-ui-ink-gray-900">
								{{ d.employee_name || d.employee }}
							</dd>
						</div>
						<div class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Jenis Cuti</dt>
							<dd class="min-w-0 flex-1 text-ui-ink-gray-900">{{ d.leave_type }}</dd>
						</div>
						<div class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Cuti Terkait</dt>
							<dd class="min-w-0 flex-1">
								<RouterLink
									:to="{
										name: 'CutiDetail',
										params: { name: d.leaves_to_adjust },
									}"
									class="font-medium text-primary underline-offset-2 hover:underline"
									>{{ d.leaves_to_adjust }}</RouterLink
								>
							</dd>
						</div>
						<div v-if="d.reason" class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Alasan</dt>
							<dd class="min-w-0 flex-1 whitespace-pre-wrap text-ui-ink-gray-900">
								{{ d.reason }}
							</dd>
						</div>
						<div v-if="d.diajukan_oleh" class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Diajukan Oleh</dt>
							<dd class="min-w-0 flex-1 text-ui-ink-gray-900">
								{{ d.diajukan_oleh }}<span v-if="d.diajukan_hr" class="text-ui-ink-gray-400">
									· HR</span
								>
							</dd>
						</div>
						<div class="flex gap-3">
							<dt class="w-32 shrink-0 text-ui-ink-gray-400">Dibuat</dt>
							<dd class="min-w-0 flex-1 text-ui-ink-gray-900">
								{{ tanggal(d.creation) }}
							</dd>
						</div>
					</dl>
				</div>

				<p
					v-if="d.alasan_penolakan"
					class="mt-4 rounded-xl bg-ui-surface-red-50 p-3 text-sm text-ui-ink-red-800"
				>
					<span class="font-medium">Alasan penolakan:</span>
					{{ d.alasan_penolakan }}
				</p>

				<!-- Ruang bawah agar konten tidak tertutup bar keputusan. -->
				<div v-if="aksi.length" class="bottom-bar-spacer" />
			</template>
		</div>

		<!-- ============ ACTION ============ -->
		<!-- Satu tombol Action + daftar aksi, sama dengan Detail Cuti. Daftarnya
		     dari server (transisi Workflow): klien tidak menebak siapa berhak apa. -->
		<div
			v-if="d && aksi.length"
			class="fixed inset-x-0 bottom-0 z-30 border-t border-ui-line-gray-100 bg-ui-surface px-4 py-3"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<div class="mx-auto flex max-w-md gap-2">
				<button
					type="button"
					class="flex flex-1 items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99]"
					@click="actionsOpen = true"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<circle cx="12" cy="12" r="1" />
						<circle cx="19" cy="12" r="1" />
						<circle cx="5" cy="12" r="1" />
					</svg>
					Action
				</button>
			</div>
		</div>

		<!-- ===== Bottom-sheet daftar Action ===== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="actionsOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="actionsOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="actionsOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2
								class="mb-4 text-center text-base font-semibold text-ui-ink-gray-900"
							>
								Action
							</h2>

							<p
								v-if="!aksi.length"
								class="py-3 text-center text-sm text-ui-ink-gray-400"
							>
								Tidak ada aksi tersedia untuk Anda.
							</p>
							<div v-else class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="a in aksi"
									:key="a.action"
									type="button"
									:disabled="!!menjalankan"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border px-4 py-3.5 text-left transition disabled:opacity-50"
									:class="
										merah(a.action)
											? 'border-ui-line-red-200 hover:border-ui-line-red-400 hover:bg-ui-surface-red-50'
											: 'border-ui-line-gray-200 hover:border-primary hover:bg-primary/5'
									"
									@click="pilihAksi(a)"
								>
									<span
										class="text-sm font-semibold"
										:class="
											merah(a.action)
												? 'text-ui-ink-red-600'
												: 'text-ui-ink-gray-800'
										"
										>{{ labelAksi(a.action) }}</span
									>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
										>→ {{ a.next_state }}</span
									>
								</button>
							</div>

							<p
								v-if="menjalankan"
								class="mt-3 text-center text-xs text-ui-ink-gray-400"
							>
								Menerapkan “{{ labelAksi(menjalankan) }}”…
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<BagiSakitSheet
			:open="keputusanOpen"
			:hari="Number(d?.hari_di_atas_batas || 0)"
			:batas="Number(d?.batas_hari_sakit || 14)"
			:saldo-tahunan="Number(d?.saldo_tahunan_tersedia || 0)"
			:memproses="!!menjalankan"
			@batal="keputusanOpen = false"
			@simpan="(v) => jalankan('Approve', null, v)"
		/>

		<!-- ============ DIALOG REJECT ============ -->
		<Transition
			enter-active-class="transition-opacity duration-200"
			enter-from-class="opacity-0"
			leave-active-class="transition-opacity duration-150"
			leave-to-class="opacity-0"
		>
			<div
				v-if="tolakBuka"
				class="fixed inset-0 z-50 flex items-end justify-center bg-black/40 sm:items-center"
				@click.self="tolakBuka = false"
			>
				<div
					class="sheet-bottom w-full max-w-md rounded-t-3xl bg-ui-surface p-5 sm:rounded-3xl"
				>
					<h2 class="text-lg font-semibold text-ui-ink-gray-900">Reject penyesuaian</h2>
					<p class="mt-1 text-sm text-ui-ink-gray-500">
						Alasan boleh dikosongkan. Jika diisi, HR dan karyawan bisa membacanya.
					</p>
					<textarea
						v-model.trim="alasanTolak"
						rows="3"
						maxlength="1000"
						placeholder="Alasan penolakan (opsional)"
						class="mt-4 w-full resize-none rounded-xl border border-ui-line-gray-200 bg-ui-surface-gray-50 p-3 text-base text-ui-ink-gray-900 placeholder:text-ui-ink-gray-400 focus:border-primary focus:bg-ui-surface focus:outline-none"
					></textarea>
					<div class="mt-5 flex gap-2">
						<button
							type="button"
							class="flex-1 rounded-xl border border-ui-line-gray-200 py-3 text-base font-medium text-ui-ink-gray-700 active:bg-ui-surface-gray-100"
							:disabled="!!menjalankan"
							@click="tolakBuka = false"
						>
							Batal
						</button>
						<button
							type="button"
							class="flex-1 rounded-xl bg-red-600 py-3 text-base font-semibold text-white active:opacity-90 disabled:opacity-60"
							:disabled="!!menjalankan"
							@click="jalankan('Reject', alasanTolak)"
						>
							{{ menjalankan === 'Reject' ? 'Memproses…' : 'Reject' }}
						</button>
					</div>
				</div>
			</div>
		</Transition>
	</div>
</template>

<script setup>
/**
 * Detail Penyesuaian Cuti.
 *
 * Yang paling ingin diketahui pembacanya adalah "dari kapan jadi kapan", jadi
 * itulah yang dipajang paling atas — rentang lama dicoret, rentang baru
 * ditonjolkan. Sisanya rincian pendukung.
 *
 * Penyesuaian diajukan karyawan dari detail cutinya (atau dibuat HR di desk) dan
 * baru berlaku setelah disetujui berurutan oleh Atasan, HR, lalu Ketua (buatan HR langsung ke Ketua). Para pemutus masuk ke halaman ini lewat
 * Workflow Requests; tombol Approve/Reject hanya muncul bila server bilang
 * gilirannya ada pada user ini.
 */
import { computed, onMounted, ref } from 'vue'
import { createResource } from 'frappe-ui'
import { rentang, angka, tanggal, statusBadge } from '../data/cutiStatus'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'
import { useBackNavigation } from '../composables/useBackNavigation'
import BagiSakitSheet from '../components/BagiSakitSheet.vue'
import { konfirmasi } from '../composables/konfirmasi'

const props = defineProps({ name: { type: String, required: true } })

const d = ref(null)

// Kembali ke cuti yang disesuaikan, bukan ke daftar penyesuaian. Yang dibuka
// dari Workflow Requests tetap kembali ke antrean itu (lewat navigation origin).
const { backLabel, goBack } = useBackNavigation(
	computed(() =>
		d.value?.leaves_to_adjust
			? { name: 'CutiDetail', params: { name: d.value.leaves_to_adjust } }
			: { name: 'PenyesuaianCuti' }
	),
	computed(() => (d.value?.leaves_to_adjust ? 'Cuti' : 'Penyesuaian Cuti'))
)
const loading = ref(true)
const error = ref('')

const aksi = ref([])
const actionsOpen = ref(false)
const menjalankan = ref('')
const tolakBuka = ref(false)
const alasanTolak = ref('')
const keputusanOpen = ref(false)

const sudahDibagi = computed(() => {
	const x = d.value
	if (!x?.hari_di_atas_batas) return false
	const t = Number(x.sakit_potong_tahunan || 0) + Number(x.sakit_non_pay || 0)
	return Math.abs(t - x.hari_di_atas_batas) < 0.001
})
const rincian = computed(() =>
	[
		{ hari: Number(d.value?.sakit_potong_tahunan || 0), label: 'potong cuti tahunan' },
		{ hari: Number(d.value?.sakit_non_pay || 0), label: 'tanpa upah' },
	].filter((b) => b.hari)
)

// Approve di tahap Ketua untuk sakit yang melewati batas: putuskan dulu.
function mintaApprove() {
	if (d.value?.status === 'Menunggu Approval Ketua' && Number(d.value?.hari_di_atas_batas) > 0) {
		keputusanOpen.value = true
		return
	}
	jalankan('Approve')
}

async function tolakPembagian() {
	const batas = d.value?.batas_hari_sakit || 14
	const setuju = await konfirmasi({
		judul: 'Tolak keputusan Ketua?',
		pesan: `Penyesuaian akan batal dan hari setelah hari kerja ke-${batas} dihitung Absen jika tidak masuk kerja.`,
		label: 'Tolak',
		bahaya: true,
	})
	if (!setuju) return
	jalankan('Tidak Setuju')
}

const rentangBaru = computed(() => {
	if (!d.value) return '—'
	return rentang(d.value.from_date, d.value.to_date)
})

// Label & warna aksi sama dengan Detail Cuti.
function merah(a) {
	return /reject|tolak|cancel|batal|tidak setuju/i.test(a || '')
}
function labelAksi(a) {
	return (
		{
			Approve: 'Setujui',
			Reject: 'Tolak',
			Setuju: 'Terima Keputusan',
			'Tidak Setuju': 'Tolak Keputusan',
		}[a] || a
	)
}

// Tiap aksi tetap melewati langkah masing-masing: Reject minta alasan, Approve
// Ketua untuk sakit lewat batas minta pembagian, Tidak Setuju minta konfirmasi.
function pilihAksi(a) {
	actionsOpen.value = false
	if (a.action === 'Reject') mintaTolak()
	else if (a.action === 'Approve') mintaApprove()
	else if (a.action === 'Tidak Setuju') tolakPembagian()
	else jalankan(a.action)
}

// Lewat endpoint portal, bukan frappe.client.get: pemilik cuti juga harus bisa
// membuka penyesuaian yang ia ajukan, sedangkan izin doctype-nya sengaja hanya
// memperlihatkan milik bawahan (supaya tidak muncul di Workflow Requests-nya).
const detail = createResource({
	url: 'juragan.api.portal.penyesuaian_cuti.get_detail',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess(data) {
		d.value = data
		loading.value = false
	},
	onError(err) {
		error.value = err?.messages?.[0] || err?.message || String(err)
		loading.value = false
	},
})

const aksiRes = createResource({
	url: 'juragan.api.portal.penyesuaian_cuti.get_aksi',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess(data) {
		aksi.value = data || []
	},
	// Wajib ada meski kosong: tanpa onError handler global memunculkan toast kedua.
	onError() {
		aksi.value = []
	},
})

const putuskanRes = createResource({
	url: 'juragan.api.portal.penyesuaian_cuti.putuskan',
	auto: false,
	onError() {},
})

function mintaTolak() {
	alasanTolak.value = ''
	tolakBuka.value = true
}

async function jalankan(action, alasan, keputusan = null) {
	if (menjalankan.value) return
	menjalankan.value = action
	try {
		await refreshCsrfToken()
		await putuskanRes.submit({
			name: props.name,
			action,
			alasan_penolakan: alasan || null,
			...(keputusan || {}),
		})
		notifySuccess(
			{
				Approve: 'Penyesuaian disetujui.',
				Setuju: 'Diterima. Penyesuaian berlaku.',
				'Tidak Setuju': 'Ditolak. Penyesuaian batal.',
			}[action] || 'Penyesuaian ditolak.'
		)
		tolakBuka.value = false
		keputusanOpen.value = false
		detail.fetch()
		aksiRes.fetch()
	} catch (e) {
		notifyError(e, 'Gagal menyimpan keputusan')
	} finally {
		menjalankan.value = ''
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	detail.fetch()
	aksiRes.fetch()
})
</script>
